/* GLTFLoader mínimo (script comum, sem módulos) para o three.js r152 do jogo.
   Suporta: .glb, malhas com esqueleto (skin), shape keys (morph targets, inclusive sparse), materiais básicos (cor + alfa),
   texturas embutidas e animações (clips). Uso: new THREE.GLTFLoader().load(url, gltf => {...}) ou .parse(arrayBuffer, '', onLoad, onError) */
(function (T) {
'use strict';
const CT = { 5120: Int8Array, 5121: Uint8Array, 5122: Int16Array, 5123: Uint16Array, 5125: Uint32Array, 5126: Float32Array };
const TS = { SCALAR: 1, VEC2: 2, VEC3: 3, VEC4: 4, MAT2: 4, MAT3: 9, MAT4: 16 };
const san = n => (T.PropertyBinding && T.PropertyBinding.sanitizeNodeName) ? T.PropertyBinding.sanitizeNodeName(n) : String(n).replace(/\s/g, '_').replace(/[\[\]\.:\/]/g, '');

class GLTFLoader {
  constructor() { this.timeout = 20000; }
  load(url, onLoad, onProgress, onError) {
    fetch(url).then(r => { if (!r.ok) throw new Error('HTTP ' + r.status + ' em ' + url); return r.arrayBuffer(); })
      .then(buf => this.parse(buf, url, onLoad, onError)).catch(e => { if (onError) onError(e); else console.error(e); });
  }
  loadAsync(url) { return new Promise((ok, no) => this.load(url, ok, null, no)); }
  parse(buf, path, onLoad, onError) {
    try { this._parse(buf, onLoad, onError); } catch (e) { if (onError) onError(e); else throw e; }
  }
  _parse(buf, onLoad, onError) {
    const dv = new DataView(buf);
    if (dv.getUint32(0, true) !== 0x46546C67) throw new Error('não é um arquivo GLB');
    let off = 12, json = null, bin = null;
    while (off < buf.byteLength) {
      const len = dv.getUint32(off, true), type = dv.getUint32(off + 4, true); off += 8;
      if (type === 0x4E4F534A) json = JSON.parse(new TextDecoder().decode(new Uint8Array(buf, off, len)));
      else if (type === 0x004E4942 && !bin) bin = buf.slice(off, off + len);
      off += len + ((4 - (len % 4)) % 4);
    }
    if (!json || !bin) throw new Error('GLB sem JSON ou sem dados binários');
    const J = json, cacheAcc = {};

    // ---------- accessors ----------
    const view = i => { const v = J.bufferViews[i]; return { off: v.byteOffset || 0, len: v.byteLength, stride: v.byteStride || 0 }; };
    function rawAccessor(i) {                                                   // devolve { arr (typed array copiada), size, norm, count }
      if (cacheAcc[i]) return cacheAcc[i];
      const a = J.accessors[i], Ctor = CT[a.componentType], size = TS[a.type], n = a.count * size;
      let arr;
      if (a.bufferView !== undefined) {
        const v = view(a.bufferView), base = v.off + (a.byteOffset || 0), esz = Ctor.BYTES_PER_ELEMENT;
        if (v.stride && v.stride !== esz * size) {                              // dados intercalados
          arr = new Ctor(n); const src = new Uint8Array(bin);
          for (let k = 0; k < a.count; k++) { const tmp = new Ctor(src.slice(base + k * v.stride, base + k * v.stride + esz * size).buffer); for (let c = 0; c < size; c++) arr[k * size + c] = tmp[c]; }
        } else arr = new Ctor(bin.slice(base, base + n * esz));
      } else arr = new Ctor(n);
      if (a.sparse) {
        const sp = a.sparse, iv = view(sp.indices.bufferView), vv = view(sp.values.bufferView), IC = CT[sp.indices.componentType];
        const idx = new IC(bin.slice(iv.off + (sp.indices.byteOffset || 0), iv.off + (sp.indices.byteOffset || 0) + sp.count * IC.BYTES_PER_ELEMENT));
        const val = new Ctor(bin.slice(vv.off + (sp.values.byteOffset || 0), vv.off + (sp.values.byteOffset || 0) + sp.count * size * Ctor.BYTES_PER_ELEMENT));
        for (let k = 0; k < sp.count; k++) for (let c = 0; c < size; c++) arr[idx[k] * size + c] = val[k * size + c];
      }
      return (cacheAcc[i] = { arr, size, norm: !!a.normalized, count: a.count });
    }
    const attr = i => { const r = rawAccessor(i); return new T.BufferAttribute(r.arr, r.size, r.norm); };

    // ---------- texturas ----------
    const pending = [], imgTex = {};
    function texture(ti, srgb) {
      const t = J.textures[ti], src = t.source, key = src + (srgb ? 's' : 'l');
      if (imgTex[key]) return imgTex[key];
      const im = J.images[src], v = view(im.bufferView), blob = new Blob([new Uint8Array(bin, v.off, v.len)], { type: im.mimeType || 'image/png' });
      const url = URL.createObjectURL(blob), img = new Image(), tex = new T.Texture(img);
      tex.flipY = false; tex.wrapS = tex.wrapT = T.RepeatWrapping; tex.anisotropy = 4;
      if (srgb) tex.colorSpace = T.SRGBColorSpace;
      pending.push(new Promise(ok => { img.onload = () => { tex.needsUpdate = true; ok(); }; img.onerror = () => ok(); setTimeout(ok, 15000); }));
      img.src = url;
      return (imgTex[key] = tex);
    }

    // ---------- materiais ----------
    const mats = (J.materials || []).map(m => {
      const pbr = m.pbrMetallicRoughness || {}, o = { name: m.name, roughness: pbr.roughnessFactor === undefined ? 1 : pbr.roughnessFactor, metalness: pbr.metallicFactor === undefined ? 1 : pbr.metallicFactor };
      if (pbr.baseColorFactor) { o.color = new T.Color(pbr.baseColorFactor[0], pbr.baseColorFactor[1], pbr.baseColorFactor[2]); if (T.ColorManagement && T.ColorManagement.enabled) o.color.convertSRGBToLinear(); }
      if (pbr.baseColorTexture) o.map = texture(pbr.baseColorTexture.index, true);
      o.side = m.doubleSided ? T.DoubleSide : T.FrontSide;
      if (m.alphaMode === 'MASK') o.alphaTest = m.alphaCutoff === undefined ? 0.5 : m.alphaCutoff;
      else if (m.alphaMode === 'BLEND') { o.transparent = true; o.depthWrite = false; }
      const mat = new T.MeshStandardMaterial(o); mat.name = m.name || ''; return mat;
    });
    const defMat = new T.MeshStandardMaterial({ color: 0xcccccc, roughness: 0.8, metalness: 0 });

    // ---------- geometrias ----------
    function geometry(p) {
      const g = new T.BufferGeometry(), A = p.attributes;
      g.setAttribute('position', attr(A.POSITION));
      if (A.NORMAL !== undefined) g.setAttribute('normal', attr(A.NORMAL));
      if (A.TEXCOORD_0 !== undefined) g.setAttribute('uv', attr(A.TEXCOORD_0));
      if (A.JOINTS_0 !== undefined) { const r = rawAccessor(A.JOINTS_0), u = new Uint16Array(r.arr); g.setAttribute('skinIndex', new T.BufferAttribute(u, 4)); }
      if (A.WEIGHTS_0 !== undefined) {
        const r = rawAccessor(A.WEIGHTS_0), f = new Float32Array(r.arr.length), s = r.norm ? (r.arr instanceof Uint8Array ? 1 / 255 : r.arr instanceof Uint16Array ? 1 / 65535 : 1) : 1;
        for (let k = 0; k < f.length; k++) f[k] = r.arr[k] * s;
        g.setAttribute('skinWeight', new T.BufferAttribute(f, 4));
      }
      if (p.indices !== undefined) { const r = rawAccessor(p.indices); g.setIndex(new T.BufferAttribute(r.arr instanceof Uint8Array ? new Uint16Array(r.arr) : r.arr, 1)); }
      if (p.targets && p.targets.length) {
        g.morphTargetsRelative = true; g.morphAttributes.position = []; const hasN = p.targets.some(t => t.NORMAL !== undefined); if (hasN) g.morphAttributes.normal = [];
        p.targets.forEach(t => {
          g.morphAttributes.position.push(t.POSITION !== undefined ? attr(t.POSITION) : new T.BufferAttribute(new Float32Array(g.attributes.position.count * 3), 3));
          if (hasN) g.morphAttributes.normal.push(t.NORMAL !== undefined ? attr(t.NORMAL) : new T.BufferAttribute(new Float32Array(g.attributes.position.count * 3), 3));
        });
      }
      g.computeBoundingSphere();
      if (g.boundingSphere) g.boundingSphere.radius = Math.max(g.boundingSphere.radius, 5);   // evita o corte pelo frustum com a pose/animação
      return g;
    }

    // ---------- nós ----------
    const jointSet = new Set(); (J.skins || []).forEach(s => s.joints.forEach(k => jointSet.add(k)));
    const nodes = J.nodes.map((n, i) => {
      const o = jointSet.has(i) ? new T.Bone() : new T.Object3D();
      o.name = san(n.name || ('node' + i)); o.userData.gltfName = n.name || '';
      if (n.matrix) { const m = new T.Matrix4().fromArray(n.matrix); m.decompose(o.position, o.quaternion, o.scale); }
      else { if (n.translation) o.position.fromArray(n.translation); if (n.rotation) o.quaternion.fromArray(n.rotation); if (n.scale) o.scale.fromArray(n.scale); }
      return o;
    });
    const used = {}; nodes.forEach(o => { if (used[o.name]) o.name = o.name + '_' + (used[o.name]++); else used[o.name] = 1; });
    const skinMeshes = [];
    J.nodes.forEach((n, i) => {
      const o = nodes[i];
      if (n.children) n.children.forEach(c => o.add(nodes[c]));
      if (n.mesh !== undefined) {
        const me = J.meshes[n.mesh], names = (me.extras && me.extras.targetNames) || [], group = new T.Group();
        group.name = o.name; group.userData.targetNames = names; group.userData.meshes = [];
        me.primitives.forEach((p, pi) => {
          const geo = geometry(p), mat = p.material !== undefined ? mats[p.material] : defMat;
          const skinned = n.skin !== undefined && p.attributes.JOINTS_0 !== undefined;
          const mesh = skinned ? new T.SkinnedMesh(geo, mat) : new T.Mesh(geo, mat);
          mesh.name = o.name + '_' + pi; mesh.frustumCulled = false;
          if (geo.morphAttributes.position) {
            mesh.updateMorphTargets();                                           // cria influences/dictionary; depois trocamos os nomes
            mesh.morphTargetDictionary = {}; names.forEach((nm, k) => { mesh.morphTargetDictionary[nm] = k; });
            if (me.weights) me.weights.forEach((w, k) => { mesh.morphTargetInfluences[k] = w; });
          }
          if (skinned) skinMeshes.push({ mesh, skin: n.skin });
          group.add(mesh); group.userData.meshes.push(mesh);
        });
        o.add(group);
      }
    });
    const scene = new T.Group(); scene.name = 'Scene';
    const sc = J.scenes[J.scene || 0]; sc.nodes.forEach(k => scene.add(nodes[k]));
    scene.updateMatrixWorld(true);

    // ---------- esqueletos ----------
    const skels = (J.skins || []).map(s => {
      const bones = s.joints.map(k => nodes[k]), inv = [];
      const ib = s.inverseBindMatrices !== undefined ? rawAccessor(s.inverseBindMatrices).arr : null;
      bones.forEach((b, k) => { const m = new T.Matrix4(); if (ib) m.fromArray(ib, k * 16); inv.push(m); });
      return new T.Skeleton(bones, inv);
    });
    skinMeshes.forEach(({ mesh, skin }) => { mesh.bind(skels[skin], mesh.matrixWorld); });

    // ---------- animações ----------
    const animations = (J.animations || []).map(a => {
      const tracks = [];
      a.channels.forEach(c => {
        const s = a.samplers[c.sampler], node = nodes[c.target.node], path = c.target.path;
        if (!node || path === 'weights') return;
        const times = Array.from(rawAccessor(s.input).arr), vals = Array.from(rawAccessor(s.output).arr);
        const nm = node.name + '.' + (path === 'translation' ? 'position' : path === 'rotation' ? 'quaternion' : 'scale');
        const Tr = path === 'rotation' ? T.QuaternionKeyframeTrack : T.VectorKeyframeTrack;
        tracks.push(new Tr(nm, times, vals, s.interpolation === 'STEP' ? T.InterpolateDiscrete : undefined));
      });
      return new T.AnimationClip(a.name || 'anim', -1, tracks);
    });

    const result = { scene, scenes: [scene], animations, skeletons: skels, nodes, asset: J.asset, parser: { json: J } };
    Promise.all(pending).then(() => onLoad(result), e => { if (onError) onError(e); });
  }
}
T.GLTFLoader = GLTFLoader;
})(window.THREE);
